public int sumPath(int row, int col) {
    // Check if the starting position is valid
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length) {
        return -1;
    }

    // Create a visited array to track our path
    boolean[][] visited = new boolean[grid.length][grid[0].length];

    // Start the recursive backtracking
    return findPath(row, col, -1, visited);
}

private int findPath(int row, int col, int prevValue, boolean[][] visited) {
    // Check if out of bounds or already visited
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || visited[row][col]) {
        return -1;
    }

    int currentValue = grid[row][col];

    // Check if this step is valid (difference ≤ 15)
    if (prevValue != -1 && Math.abs(currentValue - prevValue) > 15) {
        return -1;
    }

    // Mark as visited
    visited[row][col] = true;

    // Check if we've reached the destination (bottom-right)
    if (row == grid.length - 1 && col == grid[0].length - 1) {
        visited[row][col] = false;  // Restore for potential other paths
        return currentValue;
    }

    // Try all possible next positions using getNextLoc
